import{_ as o,C as r,o as n,c as i,j as t,a,E as l,a2 as h}from"./chunks/framework.D0xy3_1I.js";const y=JSON.parse('{"title":"5. Changelog","description":"","frontmatter":{},"headers":[],"relativePath":"gdd/changelog.md","filePath":"gdd/changelog.md"}'),d={name:"gdd/changelog.md"},g={id:"latest-main",tabindex:"-1"};function p(f,e,c,u,m,b){const s=r("Badge");return n(),i("div",null,[e[3]||(e[3]=t("h1",{id:"_5-changelog",tabindex:"-1"},[a("5. Changelog "),t("a",{class:"header-anchor",href:"#_5-changelog","aria-label":'Permalink to "5. Changelog"'},"​")],-1)),e[4]||(e[4]=t("p",null,[a("Every published version stays playable at its own URL. The "),t("a",{href:"https://thuannvathena.github.io/spot-a-fish/",target:"_blank",rel:"noreferrer"},"landing page"),a(" lists them all.")],-1)),t("h2",g,[e[0]||(e[0]=a("latest (main) ",-1)),l(s,{type:"tip",text:"Live"}),e[1]||(e[1]=a()),e[2]||(e[2]=t("a",{class:"header-anchor",href:"#latest-main","aria-label":'Permalink to "latest (main) <Badge type="tip" text="Live" />"'},"​",-1))]),e[5]||(e[5]=h('<p>Imported from the Find Fish prototype (changes since the first playtester feedback):</p><ul><li><strong>Playtest feedback:</strong> about 50–60% fewer decoy fish; fish per tank rises 1 → 2 → 3; slower, bigger fish early; long tutorial replaced by a goal popup and a pointing hand; level 1 cannot be lost; gentler stars.</li><li><strong>Fish look and motion:</strong> softer outline from the fish&#39;s own colour, less glow, more body wobble and wider tail, longer swim paths, fewer idle fish.</li><li><strong>Rewards:</strong> combo words with sparkles; every 3rd combo refills Hint.</li><li><strong>Random events:</strong> squabble, conga, waltz, swirl, hide, pearl, startle (falling object), feeding.</li><li><strong>Introductions by highlight:</strong> Backup (L2), Hint (L4), Clear Backup (L5); camera tutorial at L1.</li><li><strong>Obstacles:</strong> squid moved to L3, clam to L6; bounty tanks from L6; fish swarm from L9.</li><li><strong>Pump tube (L7+)</strong> and a fish cap (now 40 at once, also enforced for pump waves), with many display fixes so the tube is not bent by the lens.</li><li><strong>Global collision</strong> between fish, obstacles, decorations and tube.</li><li><strong>Feeding:</strong> 3D food bucket replaces the 3D hand.</li><li><strong>Water surface:</strong> smooth normals, reflections rebuilt, grid reduced for performance.</li><li><strong>Hover:</strong> double-layer gold outline on desktop.</li><li><strong>Pause menu:</strong> Reset progress.</li><li><strong>Project:</strong> moved into the docs and release structure (Three.js game kept).</li><li><strong>Phaser 4 UI layer:</strong> the top bar, target tanks (small live aquariums), tool buttons, Backup tray, popups, spotlight tips and messages are drawn by Phaser above the 3D tank. Level editor added.</li><li><strong>Clear Backup:</strong> returning fish now fly to the open top of the tank and drop in through it, with a splash, instead of appearing under the water.</li><li><strong>Glass rim and tank shell:</strong> the water lens no longer bends the glass wall, rims, stand or plinth; only what is inside the water (fish, sand, decorations, surface) is refracted.</li><li><strong>One event at a time:</strong> feeding, the pearl game, the falling rock, the swarm and tube waves now wait for each other instead of overlapping.</li><li><strong>Fixes:</strong> Clear Backup no longer freezes the game when the Backup holds obstacles (they have no tail, which the new drop animation assumed). Dropping fish now dive head first, seen in profile, and carry on in the direction they dived. The gold hover outline follows the fish silhouette again.</li><li><strong>UI style: brass and glass.</strong> The whole Phaser UI is drawn like aquarium equipment: a brass control rail with a porthole for the level and a valve wheel for pause; a glass water gauge that fills as target tanks are finished, marked with starfish (the stars of the game); hanging brass nameplates and corner brackets on the target tanks; a brass shelf with glass jars for the Backup (slimmer than before); brass-bezel tool buttons; popups in riveted brass frames with a coral banner and pearl buttons; a level list as a reef of pearls joined by stepping stones, with starfish for the stars; messages and spotlight tips with brass edges.</li><li><strong>Hover glow:</strong> the gold highlight is now a glow hull around the whole 3D fish, so it wraps the fish from any angle (before it was a flat plane that showed only as a slice when the fish faced the camera).</li><li><strong>Fish bodies:</strong> each fish is one closed, welded surface that follows the true outline of its picture, with a rounded edge, so there is no gap between the two faces. The rim is rounded with several rows of vertices following a circular profile, and vertices near the edge read the picture a few pixels inside, so there is no seam, stitch marks or pale bands even when a fish is seen head-on. The dark outline is a thin inverted hull behind the body, and the fish colours are smeared a few pixels past the outline, so edge-on views show no black tear or dots. Clear Backup fish leave the tray with a short hop and enter below it through the mouth of the tank.</li></ul><p>Detailed history is in the original project&#39;s <code>CHANGELOG.md</code>.</p><p><a href="https://thuannvathena.github.io/spot-a-fish/demo/" target="_blank" rel="noreferrer">Play latest</a></p><h2 id="document-history" tabindex="-1">Document history <a class="header-anchor" href="#document-history" aria-label="Permalink to &quot;Document history&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Date</th><th>Change</th></tr></thead><tbody><tr><td>2026-11-05</td><td>GDD created from the Find Fish prototype&#39;s handover notes and changelog</td></tr></tbody></table>',6))])}const v=o(d,[["render",p]]);export{y as __pageData,v as default};
